:root {
  --card-bg: #fdf6e3;
  --card-border: #b5956a;
  --header-bg: #7a5c3a;
  --header-text: #fdf6e3;
  --label-text: #9e7a4f;
  --blend-name: #3d2b1a;
  --herb-text: #4a3520;
  --amount-text: #7a5c3a;
  --divider: #d4b896;
  --footer-text: #8a6e4b;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
}

.recipe-card {
  background-color: var(--card-bg);
  border: 2px solid var(--card-border);
  border-radius: 6px;
  width: 300px;
  padding: 0;
  overflow: hidden;
}

.card-header {
  background-color: var(--header-bg);
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  padding: 8px 14px;
}

.card-label {
  color: var(--header-text);
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.card-number {
  color: var(--header-text);
  font-size: 18px;
  font-weight: 700;
}

.blend-name {
  color: var(--blend-name);
  font-size: 22px;
  font-weight: 700;
  text-align: center;
  margin: 14px 0 10px;
  letter-spacing: 0.04em;
}

.ingredient-list {
  list-style: none;
  margin: 0 14px;
  padding: 0;
  border-top: 1px solid var(--divider);
}

.ingredient {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 7px 0;
  border-bottom: 1px solid var(--divider);
}

.herb {
  color: var(--herb-text);
  font-size: 14px;
  font-weight: 600;
}

.amount {
  color: var(--amount-text);
  font-size: 13px;
}

.card-footer {
  padding: 9px 14px;
  text-align: center;
}

.steep {
  color: var(--footer-text);
  font-size: 12px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}
